import os
import json
import uuid
from datetime import datetime, timezone

import boto3
from botocore.exceptions import ClientError


def write_structured_log_event(
    log_group_name: str,
    log_stream_name: str,
    message: dict,
    region_name: str | None = None,
) -> dict:
    """
    Write a structured JSON log event to Amazon CloudWatch Logs.

    Requires AWS credentials via environment or configured AWS profile.
    """
    region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    if not region_name:
        raise ValueError("AWS region must be provided via region_name or AWS_REGION/AWS_DEFAULT_REGION")

    client = boto3.client("logs", region_name=region_name)

    timestamp_ms = int(datetime.now(timezone.utc).timestamp() * 1000)
    payload = {
        "event_id": str(uuid.uuid4()),
        "timestamp": datetime.now(timezone.utc).isoformat(),
        **message,
    }

    log_event = {
        "timestamp": timestamp_ms,
        "message": json.dumps(payload, separators=(",", ":"), ensure_ascii=False),
    }

    try:
        sequence_token = None
        try:
            describe_resp = client.describe_log_streams(
                logGroupName=log_group_name,
                logStreamNamePrefix=log_stream_name,
                limit=1,
            )
            streams = describe_resp.get("logStreams", [])
            if streams and streams[0].get("logStreamName") == log_stream_name:
                sequence_token = streams[0].get("uploadSequenceToken")
        except ClientError:
            sequence_token = None

        kwargs = {
            "logGroupName": log_group_name,
            "logStreamName": log_stream_name,
            "logEvents": [log_event],
        }
        if sequence_token:
            kwargs["sequenceToken"] = sequence_token

        response = client.put_log_events(**kwargs)
        return {
            "provider": "amazon-cloudwatch-logs",
            "logGroupName": log_group_name,
            "logStreamName": log_stream_name,
            "nextSequenceToken": response.get("nextSequenceToken"),
            "rejectedInfo": response.get("rejectedLogEventsInfo"),
        }
    except ClientError as e:
        raise RuntimeError(f"Failed to write log event to CloudWatch Logs: {e}") from e


if __name__ == "__main__":
    log_group = os.getenv("CLOUDWATCH_LOG_GROUP", "example-log-group")
    log_stream = os.getenv("CLOUDWATCH_LOG_STREAM", "example-log-stream")
    result = write_structured_log_event(
        log_group_name=log_group,
        log_stream_name=log_stream,
        message={
            "level": "INFO",
            "service": "managed-log-ingestion",
            "message": "Structured JSON event written to CloudWatch Logs",
        },
    )
    print(json.dumps(result, indent=2))
